const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const Thread = std.Thread;
const Tensor = @import("tensor_core.zig").Tensor;
const AstroLorenzTokenizer = @import("astro_tokenizer.zig").AstroLorenzTokenizer;
const CelestialZO = @import("celestial_optimizer.zig").CelestialZO;
const FMRNModel = @import("jaide_runtime.zig").FMRNModel;

pub const TrainingConfig = struct {
    batch_size: usize = 1024,
    epochs: usize = 400,
    learning_rate: f64 = 0.0001,
    warmup_steps: usize = 10000,
    decay_rate: f64 = 0.95,
    gradient_clip: f64 = 1.0,
    checkpoint_interval: usize = 100,
    log_interval: usize = 10,
    eval_interval: usize = 50,
    max_grad_norm: f64 = 1.0,
};

pub const TrainingMetrics = struct {
    loss: f64,
    grad_norm: f64,
    step_time: f64,
    eval_score: f64,

    pub fn toJson(self: *const TrainingMetrics, allocator: Allocator) ![]u8 {
        return std.json.stringifyAlloc(allocator, self.*, .{});
    }
};

pub const DataLoader = struct {
    allocator: Allocator,
    tokenizer: AstroLorenzTokenizer,
    batches: [][][]u8,
    labels: [][]u8,
    current_batch: usize = 0,
    shuffle: bool = true,

    pub fn init(allocator: Allocator, texts: []const []const u8, labels: []const []const u8, config: TrainingConfig) !DataLoader {
        if (texts.len == 0 or labels.len == 0) return error.EmptyDataset;
        if (texts.len != labels.len) return error.LengthMismatch;
        var tokenizer = try AstroLorenzTokenizer.init(allocator, .{ .dim = 18432 });
        errdefer tokenizer.deinit();
        const batch_size = config.batch_size;
        const num_batches = (texts.len + batch_size - 1) / batch_size;
        var loader = DataLoader{
            .allocator = allocator,
            .tokenizer = tokenizer,
            .batches = try allocator.alloc([][][]u8, num_batches),
            .labels = try allocator.alloc([][]u8, texts.len),
            .shuffle = true,
        };
        errdefer {
            allocator.free(loader.batches);
            allocator.free(loader.labels);
        }
        var prng = std.rand.DefaultPrng.init(42);
        var rng = prng.random();
        var shuffled_indices = try allocator.alloc(usize, texts.len);
        defer allocator.free(shuffled_indices);
        for (0..texts.len) |i| shuffled_indices[i] = i;
        if (loader.shuffle) {
            std.mem.shuffle(usize, shuffled_indices, rng);
        }
        for (0..texts.len) |i| {
            loader.labels[i] = try allocator.dupe(u8, labels[shuffled_indices[i]]);
        }
        for (0..loader.batches.len) |b| {
            const start = b * batch_size;
            const end_excl = @min(start + batch_size, texts.len);
            const count = end_excl - start;
            loader.batches[b] = try allocator.alloc([][]u8, count);
            for (0..count) |k| {
                const j = start + k;
                loader.batches[b][k] = try loader.tokenizer.tokenize(texts[shuffled_indices[j]]);
            }
        }
        return loader;
    }

    pub fn deinit(self: *DataLoader) void {
        for (self.batches) |batch| {
            for (batch) |item| self.allocator.free(item);
            self.allocator.free(batch);
        }
        self.allocator.free(self.batches);
        for (self.labels) |label| self.allocator.free(label);
        self.allocator.free(self.labels);
        self.tokenizer.deinit();
    }

    pub fn next_batch(self: *DataLoader) ?[][]u8 {
        if (self.current_batch >= self.batches.len) return null;
        const batch = self.batches[self.current_batch];
        self.current_batch += 1;
        return batch;
    }

    pub fn reset(self: *DataLoader) void {
        self.current_batch = 0;
    }

    pub fn embed_batch(self: *DataLoader, batch: [][]u8) !Tensor {
        const batch_len = batch.len;
        const max_len = self.max_length(batch);
        var padded = try self.allocator.alloc([][]u8, batch_len);
        defer self.allocator.free(padded);
        for (0..batch_len) |b| {
            const len = batch[b].len;
            padded[b] = try self.allocator.alloc(u8, max_len);
            @memcpy(padded[b][0..len], batch[b]);
            @memset(padded[b][len..max_len], 0);
        }
        defer for (padded) |pad| self.allocator.free(pad);
        const embeds = try self.tokenizer.padded_embed(padded, max_len);
        return embeds;
    }

    fn max_length(self: *const DataLoader, batch: [][]u8) usize {
        var m: usize = 0;
        for (batch) |item| m = @max(m, item.len);
        return m;
    }
};

pub const Trainer = struct {
    allocator: Allocator,
    model: FMRNModel,
    data_loader: DataLoader,
    config: TrainingConfig,
    optimizer: CelestialZO,
    metrics: TrainingMetrics,
    checkpoint_dir: []const u8,
    log_file: std.fs.File,

    pub fn init(allocator: Allocator, model: FMRNModel, data_loader: DataLoader, config: TrainingConfig, checkpoint_dir: []const u8) !Trainer {
        var file = try std.fs.cwd().createFile("training.log", .{ .truncate = true });
        errdefer file.close();
        return Trainer{
            .allocator = allocator,
            .model = model,
            .data_loader = data_loader,
            .config = config,
            .optimizer = model.optimizer,
            .metrics = .{ .loss = 0.0, .grad_norm = 0.0, .step_time = 0.0, .eval_score = 0.0 },
            .checkpoint_dir = checkpoint_dir,
            .log_file = file,
        };
    }

    pub fn deinit(self: *Trainer) void {
        self.log_file.close();
    }

    pub fn train_epoch(self: *Trainer) !f64 {
        self.data_loader.reset();
        var epoch_loss: f64 = 0.0;
        var step_count: usize = 0;
        const bsize = self.config.batch_size;
        while (true) {
            const batch = self.data_loader.next_batch() orelse break;
            const start_time = std.time.nanoTimestamp();
            const embeds = try self.data_loader.embed_batch(batch);
            defer embeds.deinit();
            const start_idx = step_count * bsize;
            const end_idx = @min(start_idx + batch.len, self.data_loader.labels.len);
            if (start_idx >= end_idx) break;
            const labels_batch = self.data_loader.labels[start_idx..end_idx];
            const loss = try self.model.train_step(embeds, labels_batch);
            epoch_loss += loss;
            const end_time = std.time.nanoTimestamp();
            self.metrics.step_time = @as(f64, @floatFromInt(end_time - start_time)) / 1e9;
            if (step_count % self.config.log_interval == 0) {
                try self.log_step(step_count, loss);
            }
            if (step_count % self.config.checkpoint_interval == 0) {
                try self.save_checkpoint(step_count);
            }
            step_count += 1;
        }
        if (step_count == 0) return error.NoSteps;
        return epoch_loss / @as(f64, @floatFromInt(step_count));
    }

    pub fn train(self: *Trainer) !void {
        var e: usize = 0;
        while (e < self.config.epochs) : (e += 1) {
            const epoch_loss = try self.train_epoch();
            if (e % self.config.eval_interval == 0) {
                const eval_score = try self.evaluate();
                self.metrics.eval_score = eval_score;
                try self.log_epoch(e, epoch_loss, eval_score);
            }
            if (e > self.config.warmup_steps) {
                self.config.learning_rate *= self.config.decay_rate;
                self.optimizer.config.lr = self.config.learning_rate;
                self.model.optimizer.config.lr = self.config.learning_rate;
            }
        }
    }

    fn log_step(self: *Trainer, step: usize, loss: f64) !void {
        const log_msg = try std.fmt.allocPrint(self.allocator, "Step {}: Loss = {}\n", .{ step, loss });
        defer self.allocator.free(log_msg);
        try self.log_file.writeAll(log_msg);
    }

    fn log_epoch(self: *Trainer, epoch: usize, loss: f64, eval: f64) !void {
        const log_msg = try std.fmt.allocPrint(self.allocator, "Epoch {}: Loss = {}, Eval = {}\n", .{ epoch, loss, eval });
        defer self.allocator.free(log_msg);
        try self.log_file.writeAll(log_msg);
    }

    fn save_checkpoint(self: *Trainer, step: usize) !void {
        const dir_name = try std.fmt.allocPrint(self.allocator, "step_{}", .{ step });
        defer self.allocator.free(dir_name);
        const ckpt_dir = try std.fs.path.join(self.allocator, &[_][]const u8{ self.checkpoint_dir, dir_name });
        defer self.allocator.free(ckpt_dir);
        try std.fs.cwd().makePath(ckpt_dir);
        const model_path = try std.fs.path.join(self.allocator, &[_][]const u8{ ckpt_dir, "model.weights" });
        defer self.allocator.free(model_path);
        try self.model.weights.save(model_path);
        const metrics_json = try self.metrics.toJson(self.allocator);
        defer self.allocator.free(metrics_json);
        const metrics_path = try std.fs.path.join(self.allocator, &[_][]const u8{ ckpt_dir, "metrics.json" });
        defer self.allocator.free(metrics_path);
        var metrics_file = try std.fs.cwd().createFile(metrics_path, .{ .truncate = true });
        defer metrics_file.close();
        try metrics_file.writeAll(metrics_json);
    }

    fn evaluate(self: *Trainer) !f64 {
        return error.Unimplemented;
    }
};




